import{initRouter,onContentLoaded}from"./router.js";import{initFormValidation}from"./formValidation.js";import{storage}from"./storage.js";import{renderProjects,showToast}from"./templates.js";function init(){initRouter(),initPageFeatures(),onContentLoaded(initPageFeatures),setupMenuToggle(),setupAccessibilityShortcuts()}function setupMenuToggle(){const a=document.querySelector(".menu-toggle");a&&(a.addEventListener("click",()=>{const b=document.querySelector("nav ul");if(b){b.classList.toggle("show");const c=b.classList.contains("show");a.setAttribute("aria-expanded",c)}}),a.addEventListener("keydown",b=>{("Enter"===b.key||" "===b.key)&&(b.preventDefault(),a.click())}))}function initPageFeatures(){initFormValidation();const a=document.querySelector("#projetos-list-container");if(a){const b=storage.get("projetos",getSeedProjects());renderProjects(a,b)}document.body.addEventListener("click",a=>{const b=a.target.closest(".card");b&&showToast("Voc\xEA clicou em um projeto.","info",1800)})}function getSeedProjects(){const a=[{id:1,title:"Doa\xE7\xE3o Solid\xE1ria",description:"Arrecada\xE7\xE3o e distribui\xE7\xE3o de alimentos.",img:"img/doacao.jpg",status:"Ativo"},{id:2,title:"Programa Voluntariado",description:"Capacita\xE7\xE3o e engajamento de volunt\xE1rios.",img:"img/voluntariado.jpg",status:"Em andamento"},{id:3,title:"Educar para o Futuro",description:"Oficinas de refor\xE7o escolar e inclus\xE3o digital.",img:"img/ong.png",status:"Novo"}];return storage.set("projetos",a),a}function setupAccessibilityShortcuts(){}document.addEventListener("DOMContentLoaded",init);